const item = $input.first().json;

const links = item.links ?? [];
const texts = item.link_texts ?? [];

if (links.length !== texts.length) {
  throw new Error(
    `Arrays com tamanhos diferentes: links=${links.length}, link_texts=${texts.length}`
  );
}

const baseUrl = 'https://www.faperj.br/';

const editais = links
  .map((href, index) => {
    const text = (texts[index] ?? '').trim();

    // Identifica títulos de editais originais pelo texto visível
    const match = text.match(
      /^Edital\s+FAPERJ\s*N[º°o]?\s*(\d{1,2})\s*\/\s*(202[56])\b/i
    );

    if (!match || !href.toLowerCase().includes('.pdf')) {
      return null;
    }

    const numero = match[1].padStart(2, '0');
    const ano = match[2];

    return {
      source_name: 'FAPERJ',
      external_id: `FAPERJ-${ano}-${numero}`,
      title: text.replace(/\s+/g, ' '),
      document_url: href.startsWith('http')
      ? href
      : baseUrl + href.replace(/^\/+/, '')
    };
  })
  .filter(Boolean);

const unique = [
  ...new Map(
    editais.map(edital => [
      edital.external_id,
      edital
    ])
  ).values()
];

return unique.map(edital => ({ json: edital }));

return $input.all().map(item => ({
  json: {
    source_name: item.json.source_name,
    external_id: item.json.external_id,
    title: item.json.title,
    document_url: item.json.document_url
  }
}));

const items = $input.all();

const baseUrl = 'https://www.faperj.br/';

function escapeRegex(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function validateIdentity(text, externalId) {
  const match = externalId.match(/^FAPERJ-(20\d{2})-(\d{2})$/);

  if (!match) return false;

  const [, year, number] = match;
  const safeYear = escapeRegex(year);
  const safeNumber = escapeRegex(number);

  // Procura o número e ano esperados em formatos variados
  // de cabeçalho, sem confundir referências a outros editais.
  const headerPattern = new RegExp(
    String.raw`(?:EDITAL|CHAMADA)\s+(?:CHAMADA\s+P[ÚU]BLICA\s+)?(?:FAPERJ\s*)?(?:N[º°O.]?\s*)?0?${safeNumber}\s*(?:\/\s*${safeYear}\b|[-–—][\s\S]{0,500}?\b${safeYear}\b)`,
    'i'
  );

  return headerPattern.test(text.slice(0, 12000));
}

function classifyDocument(text) {
  const normalized = text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();

  const administrativePatterns = [
    /composicao de listas triplices/,
    /listas triplices para o conselho superior/,
    /indicacao de nomes.*conselho superior/
  ];

  if (administrativePatterns.some(pattern => pattern.test(normalized))) {
    return 'administrative';
  }

  return 'funding_candidate';
}

return items.map(item => {
  const data = item.json;
  const text = data.text ?? '';

  const identityMatches = validateIdentity(
    text,
    data.external_id ?? ''
  );

  const documentType = classifyDocument(text);

  let processingStatus;

  if (!text.trim()) {
    processingStatus = 'empty_text';
  } else if (!identityMatches) {
    processingStatus = 'identity_mismatch';
  } else if (documentType === 'administrative') {
    processingStatus = 'excluded_non_funding';
  } else {
    processingStatus = 'ready';
  }

  return {
    json: {
      ...data,
      identity_matches: identityMatches,
      document_type: documentType,
      processing_status: processingStatus,
      should_analyze: processingStatus === 'ready'
    }
  };
});

const items = $input.all();

const eligible = items.filter(item =>
  item.json.should_analyze === true &&
  item.json.processing_status === 'ready' &&
  item.json.identity_matches === true &&
  item.json.document_type === 'funding_candidate'
);

return eligible.map(item => ({
  json: {
    source_name: item.json.source_name,
    external_id: item.json.external_id,
    title: item.json.title,
    document_url: item.json.document_url,
    texto_edital: item.json.text
  }
}));

const results = $input.all().map(item => item.json);

const successful = results.filter(item => item.success === true);
const failed = results.filter(item => item.success !== true);

const completed = successful.filter(
  item => item.analysis_status === 'completed'
);

const needsReview = successful.filter(
  item => item.analysis_status === 'needs_review'
);

return [
  {
    json: {
      total_processed: results.length,
      successful_count: successful.length,
      failed_count: failed.length,

      completed_count: completed.length,
      needs_review_count: needsReview.length,

      success_rate: results.length
        ? Number((successful.length / results.length * 100).toFixed(2))
        : 0,

      successful,
      failed,
      completed,
      needs_review: needsReview
    }
  }
];

const response = $json.body;
const statusCode = $json.statusCode;

const success =
  statusCode >= 200 &&
  statusCode < 300 &&
  response?.success === true;

return {
  json: {
    success,
    status_code: statusCode ?? null,
    opportunity_id: response?.data?.opportunity?.id ?? null,
    opportunity_action: response?.data?.opportunity?.action ?? null,
    analysis_id: response?.data?.analysis?.id ?? null,
    analysis_action: response?.data?.analysis?.action ?? null,
    analysis_status: response?.data?.analysis?.status ?? null,
    error: success ? null : response?.message ?? response?.error ?? 'Falha no processamento'
  }
};
